        BigDecimal each = HUNDRED.divide(BigDecimal.valueOf(ids.size()), 2, RoundingMode.HALF_EVEN);
        BigDecimal first = HUNDRED.subtract(each.multiply(BigDecimal.valueOf(ids.size() - 1)));
        for (int i = 0; i < ids.size(); i++) {
