-- The SNAPSHOTs written for a person, one row each in the order they were written: the day being left when the sheet's
-- today was changed and the person's due-total as it stood then ('n/a' when they had none). Kept in history too (see
-- V39 and V40).
CREATE TABLE person_snapshot (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT       NOT NULL REFERENCES person (id),
    day_left  DATE         NOT NULL,
    due_total VARCHAR(40)  NOT NULL
);
CREATE INDEX person_snapshot_person ON person_snapshot (person_id, id);
CREATE TABLE person_snapshot_history AS SELECT * FROM person_snapshot;
ALTER TABLE person_snapshot_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
ALTER TABLE person_snapshot_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE person_snapshot_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
CREATE INDEX person_snapshot_history_key ON person_snapshot_history (person_id, id);
CREATE TRIGGER person_snapshot_journal AFTER INSERT, UPDATE, DELETE ON person_snapshot FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
-- The sheet's pools: a name (trimmed, at most once per sheet), listed in the order added.
CREATE TABLE pool (
    sheet_id VARCHAR(255) NOT NULL,
    name VARCHAR(255) NOT NULL,
    listed BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, name)
);
-- A pool's members: a person of the sheet, at most once per pool, with a share percent (two decimals, above 0.00 and
-- at most 100.00). A person can be in several pools. A retired member's share counts 0.00 toward the pool's total.
CREATE TABLE pool_member (
    sheet_id VARCHAR(255) NOT NULL,
    pool_name VARCHAR(255) NOT NULL,
    person_id BIGINT NOT NULL,
    share DECIMAL(5, 2) NOT NULL,
    listed BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, pool_name, person_id)
);
-- A pool's members that are other pools: a pool is a member of at most one pool, with a share percent like a person's
-- (two decimals, above 0.00 and at most 100.00). A pool never contains itself through any chain, and a chain of pools is
-- at most three deep. Listed in one order with the pool's person members (the next listed of both tables).
CREATE TABLE pool_nested (
    sheet_id VARCHAR(255) NOT NULL,
    pool_name VARCHAR(255) NOT NULL,
    member_pool VARCHAR(255) NOT NULL,
    share DECIMAL(5, 2) NOT NULL,
    listed BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, member_pool)
);
-- A pool membership (a person's or a pool's) may run from a from-date to a to-date, both inclusive and each optional (null
-- is open-ended); the to-date is never before the from-date. A member whose dates do not include the sheet's today is left
-- out entirely: not in the pool's total share, not in its balance, and no cut.
ALTER TABLE pool_member ADD COLUMN from_date DATE;
ALTER TABLE pool_member ADD COLUMN to_date DATE;
ALTER TABLE pool_nested ADD COLUMN from_date DATE;
ALTER TABLE pool_nested ADD COLUMN to_date DATE;
-- The sheet's crews: a name (trimmed, at most once per sheet) and a lead, a person of the sheet; listed in the order added.
CREATE TABLE crew (
    sheet_id VARCHAR(255) NOT NULL,
    name VARCHAR(255) NOT NULL,
    lead_id BIGINT NOT NULL,
    listed BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, name)
);
-- A crew's members: people of the sheet, at most once per crew and never its lead, in the order added. A person can be in
-- several crews.
CREATE TABLE crew_member (
    sheet_id VARCHAR(255) NOT NULL,
    crew_name VARCHAR(255) NOT NULL,
    person_id BIGINT NOT NULL,
    listed BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, crew_name, person_id)
);
-- A steward may lock a period, and unlock it again: a locked period cannot be reopened. Kept in the period's history
-- too (see V40). The journal trigger is made again around the change, as in V70.
DROP TRIGGER period_journal;
ALTER TABLE period ADD COLUMN locked BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period_history ADD COLUMN locked BOOLEAN;
CREATE TRIGGER period_journal AFTER INSERT, UPDATE, DELETE ON period FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
